<template><div class="app-container manage-page"><div class="page-head"><div><h2>用户管理</h2><p>查看学生账号资料与账号状态</p></div><span>{{ total }} 位用户</span></div><div class="filter-card"><el-form :inline="true" :model="query" size="small"><el-form-item label="账号"><el-input v-model.trim="query.username" clearable placeholder="账号关键字" @keyup.enter.native="search" /></el-form-item><el-form-item><el-button @click="reset">重置</el-button><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button></el-form-item></el-form></div><div class="table-card"><el-table v-loading="loading" :data="items"><el-table-column label="用户" min-width="200"><template slot-scope="{row}"><div class="user-cell"><span class="avatar">{{ initial(row.realName||row.username) }}</span><div><strong>{{row.realName||'未填写姓名'}}</strong><small>@{{row.username}}</small></div></div></template></el-table-column><el-table-column prop="studentNo" label="学号" min-width="140" /><el-table-column prop="phone" label="手机号" min-width="140"><template slot-scope="{row}">{{row.phone||'未绑定'}}</template></el-table-column><el-table-column prop="email" label="邮箱" min-width="180"><template slot-scope="{row}">{{row.email||'未绑定'}}</template></el-table-column><el-table-column label="状态" width="100" align="center"><template slot-scope="{row}"><el-tag size="small" :type="row.status===1?'success':'danger'">{{row.status===1?'正常':'已禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="110" align="center"><template slot-scope="{row}"><el-button type="text" :class="row.status===1?'danger':'enable'" @click="toggle(row)">{{row.status===1?'禁用账号':'启用账号'}}</el-button></template></el-table-column></el-table></div><pagination :total="total" :current-page.sync="query.current" :page-size.sync="query.size" :page-sizes="[10,20,50]" @pagination="load" /></div></template>
<script>import Pagination from '@/components/Pagination';import{pageStudentUser,updateStudentUser}from'@/api/student_user';export default{name:'StudentUserManage',components:{Pagination},data(){return{loading:false,items:[],total:0,query:{current:1,size:10,username:''}}},created(){this.load()},methods:{initial(v){return String(v||'用').slice(0,1)},search(){this.query.current=1;this.load()},reset(){this.query.username='';this.search()},async load(){this.loading=true;try{const r=await pageStudentUser(this.query.current,this.query.size,{username:this.query.username});this.items=r.data.records||[];this.total=r.data.total||0}finally{this.loading=false}},async toggle(row){await this.$confirm(`确认${row.status===1?'禁用':'启用'}用户“${row.realName||row.username}”？`,'账号状态',{type:'warning'});await updateStudentUser({...row,status:row.status===1?0:1});this.$message.success('状态已更新');this.load()}}}</script>
<style scoped>.manage-page{padding:24px}.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-head h2{margin:0;color:#263b50}.page-head p{margin:7px 0 0;color:#8998a8}.page-head>span{padding:9px 14px;border-radius:10px;color:#52718e;background:#edf4fa}.filter-card,.table-card{border:1px solid #e5edf4;border-radius:14px;background:#fff}.filter-card{margin-bottom:18px;padding:18px 18px 0}.table-card{overflow:hidden}.user-cell{display:flex;align-items:center;gap:12px}.avatar{display:flex;width:42px;height:42px;align-items:center;justify-content:center;border-radius:13px;color:#fff;background:linear-gradient(135deg,#315f91,#5790c7);font-weight:600}.user-cell strong,.user-cell small{display:block}.user-cell strong{color:#2b4054}.user-cell small{margin-top:4px;color:#96a4b2}.danger{color:#e35d65}.enable{color:#2f9875}</style>
